import React from "react";
import { Link } from "react-router-dom";

function Navbar() {
  return (
    <nav style={{ padding: "10px", background: "#eee" }}>
      <Link to="/events" style={{ marginRight: "10px" }}>Events</Link>
      <Link to="/register" style={{ marginRight: "10px" }}>Register</Link>
      <Link to="/scanner" style={{ marginRight: "10px" }}>QR Scanner</Link>
      <Link to="/feedback" style={{ marginRight: "10px" }}>Feedback</Link>
      <Link to="/admin-login" style={{ marginRight: "10px" }}>Admin Login</Link>
    </nav>
  );
}

export default Navbar;
